begin;
set local search_path=extensions,public,private;
select no_plan();
insert into auth.sessions(id,user_id) select md5('pgtap-strax:'||id::text)::uuid,id from auth.users on conflict do nothing;
create function pg_temp.strax_member(p_n integer) returns void language plpgsql as $$
declare person uuid:=('10000000-0000-0000-0000-'||lpad(p_n::text,12,'0'))::uuid; begin
 perform set_config('request.jwt.claim.sub',person::text,true);
 perform set_config('request.jwt.claim.role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',person,'session_id',md5('pgtap-strax:'||person::text)::uuid,'role','authenticated')::text,true);
end $$;
insert into public.friendships(requester_id,addressee_id,status,responded_at)
values('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','accepted',now()) on conflict do nothing;
insert into public.groups(id,owner_id,name) values('98400000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','Synthetic Strax group');
insert into public.group_members(group_id,profile_id,role,status) values
('98400000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','owner','active'),
('98400000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','member','active');
select ok(not has_function_privilege('anon','public.strax_count()','execute'),'anonymous users cannot count Strax');
select ok(not has_function_privilege('authenticated','private.strax_payload(uuid,uuid)','execute'),'unchecked projection helper is private');
select ok(not has_function_privilege('authenticated','private.strax_notify(uuid,uuid,text)','execute'),'client cannot forge invitations');
select ok(not has_function_privilege('authenticated','private.finish_media_before_strax(uuid,uuid,integer,integer,text,text,text)','execute'),'legacy media bypass stays internal');
select ok(not has_table_privilege('authenticated','private.strax_participations','select'),'application notes and roster are private');
select ok(not has_table_privilege('authenticated','private.strax_shares','select'),'recipient choices are private');
select ok(not has_table_privilege('authenticated','public.strax_activities','insert'),'publication requires actor-bound RPC');
select ok(not has_column_privilege('authenticated','public.strax_activities','request_input','select'),'retry input is not publicly selected');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'strax_%' and p.prosecdef),'public Strax wrappers are invokers');
select is((select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relname like 'strax_%' and n.nspname in ('public','private') and c.relkind='r' and c.relrowsecurity),6::bigint,'all Strax tables enable RLS');
set local role authenticated;
select pg_temp.strax_member(1);
select throws_ok($$select public.strax_create('{"title":"","description":"x"}')$$,'22023','invalid_strax_input','blank title fails');
select throws_ok($$select public.strax_create('{"title":"Game","description":"","joinMode":"open"}')$$,'22023','invalid_strax_input','blank explanation fails');
select throws_ok($$select public.strax_create('{"title":"Game","description":"DM me","expiresAt":"2099-01-01"}')$$,'22023','invalid_strax_input','caller cannot forge expiry');
select throws_ok($$select public.strax_create('{"title":"Game","description":"DM me","spacesNeeded":1.2}')$$,'22023','invalid_strax_input','capacity must be integer');
select throws_ok($$select public.strax_create('{"title":"Game","description":"DM me","spacesNeeded":51}')$$,'22023','invalid_strax_input','capacity stays bounded');
select set_config('test.strax.open',(public.strax_create('{"title":" One extra player ","description":"DM me for more info","joinMode":"open","venueMode":"online","spacesNeeded":1,"requirements":"Own the game"}',
'98500000-0000-0000-0000-000000000001')->>'id'),true);
select is(public.strax_get(current_setting('test.strax.open')::uuid)->>'title','One extra player','input title trims');
select is(public.strax_get(current_setting('test.strax.open')::uuid)->>'viewerState','host','host state is explicit');
select is((public.strax_get(current_setting('test.strax.open')::uuid)->>'expiresAt')::timestamptz-(public.strax_get(current_setting('test.strax.open')::uuid)->>'createdAt')::timestamptz,interval '4 hours','deadline is exactly four hours');
select is(public.strax_create('{"title":"One extra player","description":"DM me for more info","joinMode":"open","venueMode":"online","spacesNeeded":1,"requirements":"Own the game"}',
'98500000-0000-0000-0000-000000000001')->>'id',current_setting('test.strax.open'),'unknown create response retry recovers same listing');
select throws_ok($$select public.strax_create('{"title":"Different","description":"DM me"}','98500000-0000-0000-0000-000000000001')$$,'23505','strax_request_conflict','request ID cannot change input');
select throws_ok($$select public.strax_create('{"title":"Second activity","description":"DM me"}')$$,'23514','strax_already_active','host cannot create another active listing');
select is((public.strax_count()->>'count')::int,1,'visible count includes own activity');
select is(jsonb_array_length(public.strax_discover()->'items'),1,'discovery includes online activity');
select is(jsonb_array_length(public.strax_profile_badges(array['10000000-0000-0000-0000-000000000001'::uuid])->'items'),1,'grid lookup returns tiny active badge');
select set_config('test.strax.share',public.strax_share(current_setting('test.strax.open')::uuid,true,
array['10000000-0000-0000-0000-000000000002'::uuid,'10000000-0000-0000-0000-000000000003'::uuid],
array['98400000-0000-0000-0000-000000000001'::uuid])::text,true);
select is(jsonb_array_length(current_setting('test.strax.share')::jsonb->'sent'),2,'accepted friend and active group are shared');
select is(jsonb_array_length(current_setting('test.strax.share')::jsonb->'failed'),1,'nonfriend is a precise partial failure');
select lives_ok($$select public.strax_share(current_setting('test.strax.open')::uuid,true,array['10000000-0000-0000-0000-000000000002'::uuid],array['98400000-0000-0000-0000-000000000001'::uuid])$$,'sharing retries are idempotent');
select pg_temp.strax_member(2);
select is(jsonb_array_length(public.strax_notifications()),1,'friend receives one invitation despite retry and group overlap');
select is(public.strax_notifications()->0->>'kind','invited','notification kind is typed');
select is(jsonb_array_length(public.list_notifications()),0,'Strax notices never consume Hittingar inbox paging');
select is(public.resolve_notification((public.strax_notifications()->0->>'id')::uuid)->>'type','strax','opaque notification resolves Strax');
select is(public.list_group_messages_page('98400000-0000-0000-0000-000000000001')->'items'->0->'strax'->>'id',current_setting('test.strax.open'),'group message carries a typed activity card');
select is(jsonb_array_length(public.list_group_messages_page('98400000-0000-0000-0000-000000000001')->'items'),1,'group retry inserts one message');
select throws_ok($$select public.strax_roster(current_setting('test.strax.open')::uuid)$$,'42501','strax_unavailable','viewer cannot read applicant introductions');
select throws_ok($$select public.strax_share(current_setting('test.strax.open')::uuid,true)$$,'42501','strax_unavailable','nonhost cannot broadcast activity');
select throws_ok($$select public.strax_participate(current_setting('test.strax.open')::uuid,'join')$$,'23514','strax_acknowledgement_required','join requires acknowledgement');
