select is((public.strax_participate(current_setting('test.strax.open')::uuid,'join','',true)->>'participantCount')::int,1,'repeat join cannot consume another slot');
select pg_temp.strax_member(3);
select is((public.strax_count()->>'count')::int,1,'full listings remain counted');
select is(jsonb_array_length(public.strax_discover()->'items'),1,'full listings remain discoverable');
select throws_ok($$select public.strax_participate(current_setting('test.strax.open')::uuid,'join','',true)$$,'23514','strax_full','full capacity cannot overfill');
select pg_temp.strax_member(2);
select is(public.strax_participate(current_setting('test.strax.open')::uuid,'leave')->>'viewerState','none','leave restores a slot');
select pg_temp.strax_member(3);
select is(public.strax_participate(current_setting('test.strax.open')::uuid,'join','',true)->>'viewerState','joined','a different person claims freed slot');
select pg_temp.strax_member(1);
select is(jsonb_array_length(public.strax_roster(current_setting('test.strax.open')::uuid)),2,'host sees roster including left state');
select lives_ok($$select public.strax_respond(current_setting('test.strax.open')::uuid,'10000000-0000-0000-0000-000000000003','remove')$$,'host can remove joined attendee');
select is((public.strax_get(current_setting('test.strax.open')::uuid)->>'participantCount')::int,0,'removal restores slot');
select is(public.strax_close(current_setting('test.strax.open')::uuid)->>'status','closed','host can close early');
select is((public.strax_count()->>'count')::int,0,'early close removes counter entry');
select is(jsonb_array_length(public.strax_profile_badges(array['10000000-0000-0000-0000-000000000001'::uuid])->'items'),0,'early close clears profile badge');
select lives_ok($$select public.strax_close(current_setting('test.strax.open')::uuid)$$,'close retry is idempotent');
select set_config('test.strax.apply',(public.strax_create('{"title":"Quick coffee","description":"DM me for more info","spacesNeeded":1,"address":"Public cafe"}')->>'id'),true);
select is(public.strax_get(current_setting('test.strax.apply')::uuid)->>'joinMode','application','application is default');
select pg_temp.strax_member(2);
select throws_ok($$select public.strax_participate(current_setting('test.strax.apply')::uuid,'join','',true)$$,'23514','strax_join_mode_mismatch','application listing cannot bypass host approval');
select is(public.strax_participate(current_setting('test.strax.apply')::uuid,'apply','',false)->>'viewerState','pending','application introduction and acknowledgement are optional without requirements');
select pg_temp.strax_member(3);
select is(public.strax_participate(current_setting('test.strax.apply')::uuid,'apply','I can come now',true)->>'viewerState','pending','pending applications do not reserve capacity');
select pg_temp.strax_member(1);
select is((public.strax_get(current_setting('test.strax.apply')::uuid)->>'participantCount')::int,0,'applications are excluded from accepted count');
select is(public.strax_roster(current_setting('test.strax.apply')::uuid)->1->>'introduction','I can come now','only host projection includes introduction');
select lives_ok($$select public.strax_respond(current_setting('test.strax.apply')::uuid,'10000000-0000-0000-0000-000000000002','approve')$$,'host approves application');
select throws_ok($$select public.strax_respond(current_setting('test.strax.apply')::uuid,'10000000-0000-0000-0000-000000000003','approve')$$,'23514','strax_full','approval cannot overfill last slot');
select lives_ok($$select public.strax_respond(current_setting('test.strax.apply')::uuid,'10000000-0000-0000-0000-000000000003','decline')$$,'host can decline pending applicant');
