select is(public.strax_get(current_setting('test.strax.apply')::uuid)->>'viewerState','declined','declined state is private to that applicant');
select throws_ok($$select public.strax_participate(current_setting('test.strax.apply')::uuid,'apply','Another note',true)$$,'42501','strax_participation_unavailable','declined applicant cannot repeat spam');
select pg_temp.strax_member(1);
select set_config('test.strax.upload',public.reserve_media_upload('strax',current_setting('test.strax.apply')::uuid,'image','{"tags":[]}')::text,true);
select is(public.strax_get(current_setting('test.strax.apply')::uuid)->>'photoStatus','pending','text listing stays usable while image quarantines');
select throws_ok($$select public.reserve_media_upload('strax',current_setting('test.strax.apply')::uuid,'video','{}')$$,'22023','invalid_media_metadata','Strax accepts one photo only');
select is(public.strax_reserve_media(current_setting('test.strax.apply')::uuid)->>'id',current_setting('test.strax.upload')::jsonb->>'id','image reservation retry recovers same upload');
reset role;
update private.media_uploads set status='processing',claim_id='98600000-0000-0000-0000-000000000001',expires_at=clock_timestamp()+interval '10 minutes'
where id=(current_setting('test.strax.upload')::jsonb->>'id')::uuid;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select throws_ok($$select public.finish_media_upload((current_setting('test.strax.upload')::jsonb->>'id')::uuid,'98600000-0000-0000-0000-000000000001',100,null,'wrong/path.jpg',null,null)$$,'22023','invalid_verified_media','worker cannot publish forged photo path');
select ok(public.finish_media_upload((current_setting('test.strax.upload')::jsonb->>'id')::uuid,'98600000-0000-0000-0000-000000000001',100,null,
current_setting('test.strax.apply')||'/'||(current_setting('test.strax.upload')::jsonb->>'id')||'.jpg',null,null),'established worker finalizes approved photo');
reset role;
insert into storage.objects(bucket_id,name) values('strax-media',current_setting('test.strax.apply')||'/'||(current_setting('test.strax.upload')::jsonb->>'id')||'.jpg');
set local role authenticated;
select pg_temp.strax_member(3);
select is((select count(*) from storage.objects where bucket_id='strax-media'),0::bigint,'viewer cannot mint arbitrary-lifetime photo URLs outside deadline-controlled endpoint');
select set_config('test.strax.report',public.strax_report(current_setting('test.strax.apply')::uuid,'other','Synthetic moderation report')::text,true);
select throws_ok($$select public.admin_moderate_strax(current_setting('test.strax.apply')::uuid,'hide','A documented reason')$$,'42501',null::text,'ordinary member cannot moderate Strax');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','90000000-0000-0000-0000-000000000001','session_id',md5('pgtap-strax:90000000-0000-0000-0000-000000000001')::uuid,'role','authenticated','aal','aal1')::text,true);
select throws_ok($$select public.admin_moderate_strax(current_setting('test.strax.apply')::uuid,'hide','A documented reason')$$,'42501',null::text,'staff password login without MFA cannot moderate');
select set_config('request.jwt.claims',jsonb_build_object('sub','90000000-0000-0000-0000-000000000001','session_id',md5('pgtap-strax:90000000-0000-0000-0000-000000000001')::uuid,'role','authenticated','aal','aal2')::text,true);
select is(public.admin_get_report(current_setting('test.strax.report')::uuid)->'report'->>'strax_id',current_setting('test.strax.apply'),'MFA staff report payload identifies Strax');
select is(public.admin_get_report(current_setting('test.strax.report')::uuid)->'report'->'strax_snapshot'->>'title','Quick coffee','MFA staff receives frozen public activity evidence');
select lives_ok($$select public.admin_moderate_strax(current_setting('test.strax.apply')::uuid,'hide','A documented reason')$$,'MFA staff can hide activity');
