select is((public.strax_count()->>'count')::int,0,'moderation hide removes counter entry');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',jsonb_build_object('sub','90000000-0000-0000-0000-000000000001','session_id',md5('pgtap-strax:90000000-0000-0000-0000-000000000001')::uuid,'role','authenticated','aal','aal2')::text,true);
select lives_ok($$select public.admin_moderate_strax(current_setting('test.strax.apply')::uuid,'restore','A reviewed restoration')$$,'MFA staff can restore before original deadline');
select pg_temp.strax_member(1);
select is(public.strax_get(current_setting('test.strax.apply')::uuid)->>'photoStatus','approved','approved photo state appears');
select throws_ok($$select public.strax_reserve_media(current_setting('test.strax.apply')::uuid)$$,'23514','strax_photo_limit','second approved photo is rejected');
select ok((public.export_account()->'straxActivities') is not null,'account export contains owned activities');
reset role;
select throws_ok($$update public.strax_activities set expires_at=expires_at+interval '1 hour' where id=current_setting('test.strax.apply')::uuid$$,'23514','strax_lifetime_immutable','expiry cannot be extended even by unsafe direct writes');
-- Time travel is fixture-only: disable the immutability trigger as postgres,
-- move the complete four-hour pair into the past, and immediately re-enable it.
alter table public.strax_activities disable trigger strax_clock_guard;
update public.strax_activities set created_at=moment.end_at-interval '4 hours',expires_at=moment.end_at
from (select clock_timestamp()-interval '1 second' end_at) moment where id=current_setting('test.strax.apply')::uuid;
-- Use one timestamp expression to preserve the exact pair constraint.
alter table public.strax_activities enable trigger strax_clock_guard;
set local role authenticated;
select pg_temp.strax_member(1);
select is((public.strax_count()->>'count')::int,0,'deadline excludes activity without lifecycle worker');
select is(public.strax_get(current_setting('test.strax.apply')::uuid)->>'status','expired','owner sees expired state');
